import React, { useState } from "react";

function Registration({ onRegistered }) {
  const [name, setName] = useState("");
  const [dob, setDob] = useState("");
  const [city, setCity] = useState("");

  const handleSubmit = (e) => {
    e.preventDefault();
    if (name && dob && city) {
      const touristData = {
        name,
        dob,
        city,
        blockId: `KR${Math.floor(Math.random() * 1000000)}`,
      };
      onRegistered(touristData);
    } else {
      alert("Please fill all fields before continuing!");
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-orange-100 to-amber-200 flex items-center justify-center">
      <div className="bg-white/90 p-10 rounded-2xl shadow-2xl max-w-lg w-full backdrop-blur-sm">
        <h1 className="text-3xl font-bold mb-6 text-center text-orange-600">
          🙏 Namaste Tourist
        </h1>
        <form onSubmit={handleSubmit} className="space-y-5">
          <div>
            <label className="block mb-2 font-semibold text-gray-700">
              Full Name
            </label>
            <input
              type="text"
              placeholder="Enter your full name"
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-orange-400"
              value={name}
              onChange={(e) => setName(e.target.value)}
              required
            />
          </div>

          <div>
            <label className="block mb-2 font-semibold text-gray-700">
              Date of Birth
            </label>
            <input
              type="date"
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-orange-400"
              value={dob}
              onChange={(e) => setDob(e.target.value)}
              required
            />
          </div>

          <div>
            <label className="block mb-2 font-semibold text-gray-700">
              Which City Are You Visiting?
            </label>
            <input
              type="text"
              placeholder="e.g., Jaipur, Varanasi, Udaipur..."
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-orange-400"
              value={city}
              onChange={(e) => setCity(e.target.value)}
              required
            />
          </div>

          <button
            type="submit"
            className="w-full bg-orange-500 hover:bg-orange-600 text-white font-semibold py-3 rounded-lg transition-all duration-200"
          >
            Register Tourist
          </button>
        </form>
      </div>
    </div>
  );
}

export default Registration;
